result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "appconfig/__init__.py", "content": """"12-factor config loader.

Precedence (highest to lowest):
    1. CLI flags      (--port 9000)
    2. Environment    (APP_PORT=9000)
    3. Config file    (JSON)
    4. Schema defaults
"""

import json

__all__ = ["ConfigError", "load"]

_ENV_PREFIX = "APP_"

_TRUE_VALUES = {"1", "true", "yes", "on"}
_FALSE_VALUES = {"0", "false", "no", "off"}


class ConfigError(Exception):
    """Raised for any configuration problem."""


def _coerce(key, raw_value, expected_type):
    """Coerce a string/raw value to expected_type, raising ConfigError on failure."""
    if expected_type is bool:
        if isinstance(raw_value, bool):
            return raw_value
        text = str(raw_value).strip().lower()
        if text in _TRUE_VALUES:
            return True
        if text in _FALSE_VALUES:
            return False
        raise ConfigError(
            f"invalid boolean value for '{key}': {raw_value!r} "
            "(expected one of: 1/true/yes/on, 0/false/no/off)"
        )
    if expected_type is int:
        try:
            if isinstance(raw_value, bool):
                raise ValueError("bool is not an int")
            return int(str(raw_value).strip())
        except (ValueError, TypeError):
            raise ConfigError(
                f"invalid integer value for '{key}': {raw_value!r}"
            ) from None
    if expected_type is float:
        try:
            if isinstance(raw_value, bool):
                raise ValueError("bool is not a float")
            return float(str(raw_value).strip())
        except (ValueError, TypeError):
            raise ConfigError(
                f"invalid float value for '{key}': {raw_value!r}"
            ) from None
    if expected_type is str:
        if isinstance(raw_value, (str, int, float)):
            return str(raw_value)
        raise ConfigError(f"invalid string value for '{key}': {raw_value!r}")
    # Fallback: pass through anything already of the right type.
    if isinstance(raw_value, expected_type):
        return raw_value
    raise ConfigError(
        f"invalid {getattr(expected_type, '__name__', expected_type)} value "
        f"for '{key}': {raw_value!r}"
    )


def _parse_cli_args(argv, schema_keys):
    """Extract supported flags from argv into {key: raw_string_value}."""
    found = {}
    i = 0
    while i < len(len_args := argv) and i < len(argv):
        arg = argv[i]
        if not arg.startswith("--"):
            i += 1
            continue
        body = arg[2:]
        name, sep, inline_value = body.partition("=")
        if name not in schema_keys:
            # Unknown flags are ignored (e.g. consumed by other tooling).
            i += 1
            continue
        if sep:  # --port=9000
            found[name] = inline_value
            i += 1
            continue
        expected_type = schema_keys[name]
        if expected_type is bool:
            # Boolean flag: presence means true; optional explicit value allowed.
            nxt = argv[i + 1] if i + 1 < len(argv) else None
            if nxt is not None and nxt.lower() in (_TRUE_VALUES | _FALSE_VALUES):
                found[name] = nxt
                i += 2
            else:
                found[name] = "true"
                i += 1
        else:
            nxt = argv[i + 1] if i + 1 < len(argv) else None
            if nxt is None:
                raise ConfigError(f"missing value for command-line flag '--{name}'")
            found[name] = nxt
            i += 2
    return found


def load(schema, argv=None, environ=None, config_file=None):
    """Load configuration according to *schema*.

    Args:
        schema: dict mapping key -> {'type': type, 'default': any,
                'required': bool}
        argv: list of CLI args, e.g. ['--port', '9000'] or None.
        environ: dict-like of environment variables, e.g. os.environ or None.
        config_file: path to a JSON config file, or None.

    Returns:
        dict mapping key -> coerced value.

    Raises:
        ConfigError: on unknown file keys, bad values, or missing required keys
            (all missing keys reported at once).
    """
    argv = [] if argv is None else list(argv)
    environ = {} if environ is None else dict(environ)

    types = {}
    for key, spec in schema.items():
        if "type" not in spec:
            raise ConfigError(f"schema entry '{key}' is missing 'type'")
        types[key] = spec["type"]

    # --- Layer 4: defaults -------------------------------------------------
    values = {}
    sources = {}
    for key, spec in schema.items():
        if "default" in spec:
            values[key] = spec["default"]
            sources[key] = "default"

    # --- Layer 3: config file ----------------------------------------------
    file_data = {}
    if config_file is not None:
        with open(config_file, "r", encoding="utf-8") as fh:
            loaded = json.load(fh)
        if not isinstance(loaded, dict):
            raise ConfigError(
                f"config file {config_file!r} must contain a JSON object"
            )
        unknown = sorted(set(loaded) - set(types))
        if unknown:
            raise ConfigError(
                "unknown key(s) in config file: " + ", ".join(unknown)
            )
        file_data = loaded
        for key, raw in loaded.items():
            values[key] = _coerce(key, raw, types[key])
            sources[key] = "file"

    # --- Layer 2: environment ----------------------------------------------
    for key in types:
        env_name = _ENV_PREFIX + key.upper()
        if env_name in environ:
            values[key] = _coerce(key, environ[env_name], types[key])
            sources[key] = "env"

    # --- Layer 1: CLI flags --------------------------------------------------
    cli_values = _parse_cli_args(argv, {k: t for k, t in types.items()})
    for key, raw in cli_values.items():
        values[key] = _coerce(key, raw, types[key])
        sources[key] = "cli"

    # --- Required check (aggregated) -----------------------------------------
    missing = sorted(
        key
        for key, spec in schema.items()
        if spec.get("required") and key not in values
    )
    if missing:
        raise ConfigError("missing required key(s): " + ", ".join(missing))

    return values
